import{c as t,Q as o,j as i,m as s}from"./chunks/framework.CyZn50Me.js";const p=JSON.parse('{"title":"ADR-075 — Narrow exception #2 to \\"no client storage\\": one functional cookie for Curator Tour resume","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-075.md","filePath":"adr/ADR-075.md"}'),a={name:"adr/ADR-075.md"};function r(n,e,l,c,d,u){return o(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="adr-075-—-narrow-exception-2-to-no-client-storage-one-functional-cookie-for-curator-tour-resume" tabindex="-1">ADR-075 — Narrow exception #2 to &quot;no client storage&quot;: one functional cookie for Curator Tour resume <a class="header-anchor" href="#adr-075-—-narrow-exception-2-to-no-client-storage-one-functional-cookie-for-curator-tour-resume" aria-label="Permalink to &quot;ADR-075 — Narrow exception #2 to &quot;no client storage&quot;: one functional cookie for Curator Tour resume&quot;">​</a></h1><blockquote><p>Status · Accepted Date · 2026-06-03 Owner · Marko Supersedes (in part) · PRD-016 M8 (&quot;Heard-state tracking is <strong>in-memory only</strong>, runtime-scoped (lost on reload)&quot;) — narrows to the specific case of tour-position resume; heard-state remains in-memory. Related ADRs · ADR-057 (<code>orrery_locale</code> cookie — sibling pattern that establishes &quot;one cookie, one purpose, one ADR each&quot;), ADR-024 (URL-as-state for missions), ADR-029 (PWA + visit-counter in runtime memory), ADR-044 (URL-as-state for locale), ADR-055 (Science Lens — runtime-only) Closes into · PRD-016 §should-have S9, RFC-019 §11.3</p></blockquote><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The Curator Full Tour shipped in v0.7 as a 21-episode, ~66-minute auto-advancing playlist (PRD-016 / RFC-019, epic #146). It is the longest editorial commitment Orrery asks of a visitor — significantly longer than the listen-through median for any single screen episode. Realistically, most visitors who start the tour will not finish it in one sitting.</p><p>Per <strong>PRD-016 M8</strong> + <strong>WILL-NOT-HAVE</strong>, tour and heard-state are explicitly runtime-only: &quot;in-memory only, runtime-scoped (lost on reload). ADR-057 forbids localStorage.&quot; The visitor closes the tab and starts over from <code>pale-blue-dot</code> on the next visit.</p><p>ADR-057 already established the pattern for a narrow exception when the absolute rule is actively hurting a clearly bounded UX: <strong>one cookie, one purpose, one ADR each</strong>. The locale-override case (ADR-057) and the tour-resume case have identical shape — a single user-set state, lost on reload, where the friction is real and the storage payload is tiny.</p><p>This ADR opens that exception for tour resume only.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>Allow one additional cookie</strong>, scoped narrowly to Curator Tour resume state.</p><h3 id="the-exception" tabindex="-1">The exception <a class="header-anchor" href="#the-exception" aria-label="Permalink to &quot;The exception&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Name</td><td><code>orrery_tour</code></td></tr><tr><td>Value</td><td>URL-encoded JSON: \`{&quot;ep&quot;:&quot;{episode-id}&quot;,&quot;pos&quot;:{positionSec},&quot;idx&quot;:{tourIndex},&quot;cmp&quot;:0</td></tr><tr><td><code>SameSite</code></td><td><code>Lax</code></td></tr><tr><td><code>Secure</code></td><td><code>true</code> (production builds; omitted on <code>http://localhost</code> for dev)</td></tr><tr><td><code>HttpOnly</code></td><td><code>false</code> (must be readable from <code>document.cookie</code> — there is no server)</td></tr><tr><td><code>Max-Age</code></td><td><code>2592000</code> (30 days — shorter than ADR-057&#39;s 365 because tour state ages out faster than locale preference)</td></tr><tr><td><code>Path</code></td><td><code>/</code></td></tr><tr><td>Set when</td><td>Tour is active. Throttled write every ~5 s during playback; explicit write on pause, overlay close, episode boundary advance</td></tr><tr><td><strong>Cleared</strong> when</td><td>User clicks &quot;Stop tour&quot; button; tour reaches <code>capability-ladder-close</code> end; cookie payload fails schema validation on read</td></tr><tr><td><strong>Never</strong> set when</td><td>Tour is not active; a single episode plays via inventory click (per-episode resume is explicitly out of scope)</td></tr></tbody></table><h3 id="payload-schema" tabindex="-1">Payload schema <a class="header-anchor" href="#payload-schema" aria-label="Permalink to &quot;Payload schema&quot;">​</a></h3><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">interface</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> TourResumeCookie</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  ep</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// episode id, must exist in audio registry on read</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  pos</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> number</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// positionSec, finite, 0 ≤ pos ≤ episode duration</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  idx</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> number</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// tourIndex, integer, 0 ≤ idx &lt; tourSequence.length</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  cmp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// compact-mode flag at last write</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Total wire size: ~55–70 bytes URL-encoded. Well under cookie size limits.</p><h3 id="resolution-on-visit" tabindex="-1">Resolution on visit <a class="header-anchor" href="#resolution-on-visit" aria-label="Permalink to &quot;Resolution on visit&quot;">​</a></h3><ol><li>On <code>audio</code> state init, read <code>orrery_tour</code>.</li><li>If parse fails OR <code>ep</code> not in registry OR <code>idx &gt;= CURATOR_FULL_TOUR.length</code> → ignore + clear the cookie. Don&#39;t surface an error to the user.</li><li>If valid, present an explicit <strong>&quot;Resume tour where you left off?&quot;</strong> affordance in the AudioOverlay header — a one-click button, not autoplay. (Browser autoplay rules require a user gesture for audio anyway; we make the gesture explicit.)</li><li>User clicks → restore <code>tourActive=true</code>, <code>tourIndex</code>, load the episode, seek to <code>pos</code>, restore <code>compact</code> mode if set, begin playback.</li><li>User dismisses (Esc or × on the resume prompt) → clear the cookie, start fresh.</li></ol><h3 id="constraints-on-what-this-exception-unlocks" tabindex="-1">Constraints on what this exception unlocks <a class="header-anchor" href="#constraints-on-what-this-exception-unlocks" aria-label="Permalink to &quot;Constraints on what this exception unlocks&quot;">​</a></h3><p>This ADR is <strong>explicitly scoped to Curator Tour resume only</strong>. It does <strong>not</strong> open the door to:</p><ul><li>Persistent <strong>heard-episode</strong> state (PRD-016 §will-not-have line still binding).</li><li>Per-episode resume for inventory clicks outside the tour.</li><li>Speed preference, CC default, A/B provider preference persistence (all stay runtime-only).</li><li>Autoplay-prompt visit counter (ADR-029 still binding).</li><li>Any analytics / tracking cookie.</li><li>Any cookie that stores anything other than the four fields specified above.</li></ul><p>Future expansion to cover any of the above requires its own ADR with explicit reasoning. The default answer for any new &quot;should we cookie X?&quot; question stays <em>no</em>. ADR-057&#39;s discipline carries forward here.</p><h3 id="compliance" tabindex="-1">Compliance <a class="header-anchor" href="#compliance" aria-label="Permalink to &quot;Compliance&quot;">​</a></h3><p><code>orrery_tour</code> is a <strong>strictly necessary / functional preference cookie</strong> under ePrivacy Directive (EU 2002/58/EC, as amended) and GDPR Recital 30 — same class as <code>orrery_locale</code> (ADR-057). It stores only the position the user paused at, contains no personal data, no identifier, no tracking. <strong>No consent banner is required.</strong> Documented in <code>/credits</code> alongside the <code>orrery_locale</code> line.</p><h3 id="implementation-surface" tabindex="-1">Implementation surface <a class="header-anchor" href="#implementation-surface" aria-label="Permalink to &quot;Implementation surface&quot;">​</a></h3><ul><li><code>src/lib/audio-tour-cookie.ts</code> — new module: <code>readTourCookie()</code>, <code>writeTourCookie(state)</code>, <code>clearTourCookie()</code>, schema validation, debounced write helper (~5 s).</li><li><code>src/lib/audio-state.svelte.ts</code> — call writer on state transitions (<code>tourIndex</code> change, <code>positionSec</code> throttled, <code>compact</code> flag toggle); call clearer on <code>stopTour()</code> + natural end.</li><li><code>src/lib/components/AudioOverlay.svelte</code> — &quot;Resume tour?&quot; affordance when cookie present at mount; wire restore handler.</li><li><code>src/lib/audio-tour-cookie.test.ts</code> — unit tests for cookie round-trip, schema validation, payload-too-large guard, debounce timer.</li><li><code>tests/e2e/audio-tour-resume.spec.ts</code> — new e2e: start tour → advance two episodes → seek mid-episode → close tab → reopen → resume prompt appears → click → playback resumes at exact <code>(episode, position)</code>.</li><li>Update <strong>PRD-016 §M8</strong> to reference this ADR as the narrow exception (heard-state otherwise unchanged).</li><li>Update <strong>PRD-016 §will-not-have</strong> to refine &quot;Persistent heard-state&quot; wording — heard-state still NOT persisted; tour resume IS, narrowly.</li><li>Update <code>docs/adr/TA.md</code> §components Audio narration with the cookie line.</li><li>Update <code>docs/adr/index.md</code> to add this ADR.</li><li>Update <code>/credits</code> privacy blurb to mention <code>orrery_tour</code> alongside <code>orrery_locale</code>.</li></ul><p><strong>Estimate:</strong> ~120 LOC across helpers + state wiring + overlay affordance; 4 unit tests; 1 e2e test; 5 doc updates.</p><h2 id="rationale" tabindex="-1">Rationale <a class="header-anchor" href="#rationale" aria-label="Permalink to &quot;Rationale&quot;">​</a></h2><p>Tour resume is the single case where the runtime-only constraint creates a meaningful editorial loss. The Curator Full Tour is the museum experience — 66 minutes, documentary order, the Atmospheric Moves landing in sequence. Asking the visitor to restart from <code>pale-blue-dot</code> every time they close the tab discourages the long listen-through that the §success-criteria explicitly measures (&quot;≥ 10 minutes stay&quot; as the museum-grade atmosphere proxy).</p><p>ADR-057 already proved the pattern works: narrowly scoped, ADR-gated, no consent banner, no slippery slope. The codebase has stayed disciplined since. A second narrow exception under the same discipline is the principled extension, not a slope.</p><p>Keeping the resume payload to a fixed 4-field schema with a read-time validator + cookie-clear on schema mismatch means a single mistake in the cookie format can never cascade into a broken overlay state — the cookie either parses cleanly or is treated as absent.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><ul><li><strong>Status quo (in-memory only).</strong> Honest about ADR-057 spirit. Costs the editorial loss every visitor hits after closing the tab mid-tour. The friction is real and central to the museum-grade goal.</li><li><strong>URL-as-state — <code>?audio=ID&amp;t=120&amp;tour=1</code>.</strong> Fits ADR-024 / ADR-044 precedent perfectly. Cost: user has to bookmark or copy the URL themselves. &quot;Close tab, come back later&quot; doesn&#39;t auto-resume. Considered + rejected as the primary path; can still be added orthogonally as a share-link feature without superseding this ADR.</li><li><strong><code>localStorage</code>.</strong> Same reasons as ADR-057: blocks main thread, industry moved away, no advantage over a cookie for a tiny preference payload, fights the rule history.</li><li><strong>IndexedDB.</strong> Over-engineered for ~70 bytes. Reject.</li><li><strong>Service Worker cache as state store.</strong> Misuses the SW. Reject.</li><li><strong>Hybrid (cookie just caches the last tour URL).</strong> Cleaner story but requires the URL-as-state work as a prerequisite; introduces two coupled changes instead of one. Considered + rejected for v0.8; revisit if URL-as-state for audio lands separately.</li><li><strong>Open the rule wholesale.</strong> Loses ADR-057&#39;s discipline. Reject.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Positive:</strong></p><ul><li>Closes the editorial loss the absolute no-storage rule was creating for the Curator Tour.</li><li>Keeps URL still canonical for share semantics (URL &gt; cookie &gt; defaults — same precedence as ADR-057 implies for any future scoped storage).</li><li>Preserves zero-tracking / no-banner stance.</li><li>Reinforces the established precedent: <em>one cookie, one purpose, one ADR each.</em></li><li>Enables the v0.8 &quot;minimized tour&quot; UX (PRD-016 §S8) to remember its compact-state across sessions for free.</li></ul><p><strong>Negative:</strong></p><ul><li>Second cookie. The maintainer must enforce the &quot;default is no&quot; discipline against future &quot;just one more cookie?&quot; requests under their own ADRs.</li><li>Adds ~120 LOC + test surface to maintain.</li><li>Adds a small read-time validation surface — malformed cookies (manual user tampering, browser-extension interference) must clear cleanly without breaking the overlay.</li><li>Marginally complicates the &quot;I cleared my cookies&quot; story for tour resume — clearing cookies restarts the tour from <code>pale-blue-dot</code>. Acceptable; clearly documented in <code>/credits</code>.</li></ul><h2 id="decision-status" tabindex="-1">Decision status <a class="header-anchor" href="#decision-status" aria-label="Permalink to &quot;Decision status&quot;">​</a></h2><p><strong>Accepted on 2026-06-03 by Marko</strong> as part of the v0.7 tour-v2 work-block kickoff (GH #300). Implementation lands in <code>src/lib/audio-tour-cookie.ts</code> + state wiring in <code>src/lib/audio-state.svelte.ts</code> + Resume-tour affordance in <code>src/lib/components/AudioOverlay.svelte</code>, with unit tests + an e2e cookie-resume spec.</p><hr><p><em>ADR-075 · Orrery · Curator Tour resume cookie · narrow second exception to no-client-storage</em></p>`,40)])])}const m=t(a,[["render",r]]);export{p as __pageData,m as default};
